import{_ as t,o as a,c as o,ae as s}from"./chunks/framework.sRTLHEzD.js";const i="/heidrun_code/screenshots/features/past_chats.png",m=JSON.parse('{"title":"The Past chats sidebar section","description":"Find an old chat of Claude Code or Codex with its summary, its dynamic topics, its issues, and its estimated cost, and open it again.","frontmatter":{"description":"Find an old chat of Claude Code or Codex with its summary, its dynamic topics, its issues, and its estimated cost, and open it again."},"headers":[],"relativePath":"features/past_chats.md","filePath":"features/past_chats.md"}'),h={name:"features/past_chats.md"};function n(d,e,c,r,l,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="the-past-chats-sidebar-section" tabindex="-1">The Past chats sidebar section <a class="header-anchor" href="#the-past-chats-sidebar-section" aria-label="Permalink to &quot;The Past chats sidebar section&quot;">​</a></h1><p>Claude Code and Codex save each chat in a file on your computer. After a few weeks, you have hundreds of chats, and you cannot find the chat where you fixed that bug.</p><h2 id="what-heidrun-code-does" tabindex="-1">What Heidrun Code does <a class="header-anchor" href="#what-heidrun-code-does" aria-label="Permalink to &quot;What Heidrun Code does&quot;">​</a></h2><p>The Past chats sidebar section, in the right sidebar, lists the chats of the selected workspace: the chats of the coding agents that ran in the folder of the workspace. A selector at the top chooses the coding agent: Claude Code or Codex.</p><p>Under the title of each chat, a summary of up to four lines shows:</p><ul><li>The first date and the last date of the chat, and the number of messages that you typed.</li><li>The issues and the pull requests that the chat mentions.</li><li>The files that the coding agent wrote.</li><li>The worktrees where the coding agent worked.</li></ul><p>Click a line of the summary to see more in an information card. The information card of the dates also gives the tokens of the chat and its estimated cost: what the tokens would cost at the public price of the model. On a subscription, you pay something else.</p><p><img src="'+i+'" alt="The Past chats sidebar section with the selector of the coding agent, the Chats sort dropdown menu, the dynamic topic bar, and four chats with their dynamic topics and their summary." width="300"></p><h2 id="open-an-old-chat-again" tabindex="-1">Open an old chat again <a class="header-anchor" href="#open-an-old-chat-again" aria-label="Permalink to &quot;Open an old chat again&quot;">​</a></h2><p>Each row has two buttons:</p><ul><li>Open the chat in the desktop application of Claude or of Codex.</li><li>Open the chat in a new tab of Heidrun Code: Heidrun Code types the command that resumes the chat in the terminal.</li></ul><h2 id="sort-the-chats" tabindex="-1">Sort the chats <a class="header-anchor" href="#sort-the-chats" aria-label="Permalink to &quot;Sort the chats&quot;">​</a></h2><p>The Chats sort dropdown menu sorts the chats by the date of creation, the date of the last update, the number of messages that you typed, the issues, the pull requests, or the files written, in the ascending or the descending order.</p><h2 id="the-dynamic-topics" tabindex="-1">The dynamic topics <a class="header-anchor" href="#the-dynamic-topics" aria-label="Permalink to &quot;The dynamic topics&quot;">​</a></h2><p>Each chat gets up to three dynamic topics: short labels such as &quot;sidebar&quot; or &quot;release&quot;. The dynamic topic bar, at the top of the Past chats sidebar section, lists the dynamic topics of the chats. Click a dynamic topic to show only the chats that have it, and click &quot;All&quot; to show every chat again.</p><p>The section &quot;Dynamic topics&quot; of the Settings window chooses how Heidrun Code finds the dynamic topics:</p><ul><li>&quot;Keyword&quot;, the default: Heidrun Code finds the most important words of each chat on your computer, with no language model.</li><li>&quot;Language model&quot;: a coding agent that is installed on your computer finds the dynamic topics.</li></ul><p>The option &quot;Enable clustered dynamic topics&quot; puts the dynamic topics with a close meaning together, so that one subject has one label. The option &quot;Enable dynamic topics&quot; switches the dynamic topics off. What each option sends to a coding agent is on the page <a href="/heidrun_code/features/ai.html">The use of AI</a>.</p><p><em>The skalds remember every battle of the einherjar. Heidrun Code remembers every chat of your coding agents.</em></p>',19)])])}const f=t(h,[["render",n]]);export{m as __pageData,f as default};
